ROOT.scriptdef:
IF EXISTS(SELECT * FROM sys.indexes WHERE object_id = OBJECT_ID(N'CDN.DaneBinarne') AND name = N'DABKod')
  DROP INDEX DABKod on CDN.DaneBinarne;
IF EXISTS(SELECT * FROM sys.indexes WHERE object_id = OBJECT_ID(N'CDN.DaneBinarne') AND name = N'DABProcID')
  DROP INDEX DABProcID on CDN.DaneBinarne;
IF EXISTS(SELECT * FROM sys.indexes WHERE object_id = OBJECT_ID(N'CDN.DaneBinarne') AND name = N'DABDataKod')
  DROP INDEX DABDataKod on CDN.DaneBinarne;
IF OBJECT_ID('CDN.DF_DAB_Kod','D') IS NOT NULL ALTER TABLE CDN.DaneBinarne DROP CONSTRAINT DF_DAB_Kod;
ALTER TABLE CDN.DaneBinarne ALTER COLUMN DAB_Kod VARCHAR (   99)   ;

